PRAGMA defer_foreign_keys=ON;
CREATE TABLE family_request_roots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),recipient_id TEXT NOT NULL REFERENCES users(id),serial INTEGER NOT NULL CHECK(serial>0),request_number TEXT NOT NULL,title TEXT NOT NULL,request_kind TEXT NOT NULL CHECK(request_kind IN('appointment','leave')),time_status TEXT NOT NULL CHECK(time_status IN('unknown','recorded')),requested_start TEXT,requested_end TEXT,request_note TEXT NOT NULL,first_event_id TEXT NOT NULL UNIQUE REFERENCES family_request_events(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,request_number),FOREIGN KEY(first_event_id,id) REFERENCES family_request_events(id,root_id) DEFERRABLE INITIALLY DEFERRED,CHECK(time_status='unknown' AND requested_start IS NULL AND requested_end IS NULL OR time_status='recorded' AND requested_start IS NOT NULL AND requested_end IS NOT NULL AND requested_start<requested_end),CHECK(request_kind='leave' OR time_status='recorded'));
CREATE TABLE family_request_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_request_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('submit','acknowledge','request_information','respond','withdraw','close')),status TEXT NOT NULL CHECK(status IN('submitted','received','information_needed','responded','withdrawn','closed')),public_note TEXT NOT NULL,internal_reason TEXT,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,root_id));
CREATE VIEW family_request_current AS SELECT e.* FROM family_request_events e WHERE e.revision=(SELECT max(revision) FROM family_request_events WHERE root_id=e.root_id);
CREATE TRIGGER family_request_root_source BEFORE INSERT ON family_request_roots BEGIN SELECT CASE WHEN NEW.created_by<>NEW.recipient_id OR NOT EXISTS(SELECT 1 FROM customers c JOIN guardian_links g ON g.customer_id=c.id AND g.user_id=NEW.recipient_id JOIN users u ON u.id=g.user_id LEFT JOIN user_security s ON s.user_id=u.id WHERE c.id=NEW.customer_id AND c.store_id=NEW.store_id AND c.created_at<=NEW.created_at AND g.active=1 AND u.active=1 AND u.role='guardian' AND coalesce(s.must_change_password,0)=0) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM family_request_roots WHERE store_id=NEW.store_id),1) OR NEW.request_number IS NOT 'FR-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'family request fixed current authorized identity/source') END;END;
CREATE TRIGGER family_request_event_source BEFORE INSERT ON family_request_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_request_roots WHERE id=NEW.root_id AND store_id=NEW.store_id) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM family_request_events WHERE root_id=NEW.root_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_request_events WHERE store_id=NEW.store_id),1) OR NEW.action='submit' AND NOT EXISTS(SELECT 1 FROM family_request_roots r WHERE r.id=NEW.root_id AND r.first_event_id=NEW.id AND NEW.revision=1 AND NEW.status='submitted' AND r.created_by=NEW.created_by AND r.created_at=NEW.created_at AND r.request_note=NEW.public_note AND NEW.internal_reason IS NULL) OR NEW.action<>'submit' AND NOT EXISTS(SELECT 1 FROM family_request_current c WHERE c.root_id=NEW.root_id AND c.status NOT IN('withdrawn','closed')) OR NEW.status IS NOT CASE NEW.action WHEN 'submit' THEN 'submitted' WHEN 'acknowledge' THEN 'received' WHEN 'request_information' THEN 'information_needed' WHEN 'respond' THEN 'responded' WHEN 'withdraw' THEN 'withdrawn' WHEN 'close' THEN 'closed' END THEN RAISE(ABORT,'family request explicit continuous current action') END;END;
CREATE TRIGGER family_request_event_actor BEFORE INSERT ON family_request_events BEGIN SELECT CASE WHEN NEW.action IN('submit','withdraw') AND (NEW.internal_reason IS NOT NULL OR NOT EXISTS(SELECT 1 FROM family_request_roots r JOIN users u ON u.id=r.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=r.customer_id LEFT JOIN user_security s ON s.user_id=u.id WHERE r.id=NEW.root_id AND u.id=NEW.created_by AND u.active=1 AND u.role='guardian' AND g.active=1 AND coalesce(s.must_change_password,0)=0)) OR NEW.action NOT IN('submit','withdraw') AND (NEW.internal_reason IS NULL OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(s.must_change_password,0)=0) OR NEW.action<>'close' AND NOT EXISTS(SELECT 1 FROM family_request_roots r JOIN users u ON u.id=r.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=r.customer_id LEFT JOIN user_security s ON s.user_id=u.id WHERE r.id=NEW.root_id AND u.active=1 AND u.role='guardian' AND g.active=1 AND coalesce(s.must_change_password,0)=0)) THEN RAISE(ABORT,'family request current actor/authorization') END;END;
CREATE TRIGGER family_request_roots_time BEFORE INSERT ON family_request_roots WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_request_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family request canonical nondecreasing saved time');END;
CREATE TRIGGER family_request_roots_no_update BEFORE UPDATE ON family_request_roots BEGIN SELECT RAISE(ABORT,'family request immutable');END;
CREATE TRIGGER family_request_roots_no_delete BEFORE DELETE ON family_request_roots BEGIN SELECT RAISE(ABORT,'family request immutable');END;
CREATE TRIGGER family_request_events_time BEFORE INSERT ON family_request_events WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_request_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family request canonical nondecreasing saved time');END;
CREATE TRIGGER family_request_events_no_update BEFORE UPDATE ON family_request_events BEGIN SELECT RAISE(ABORT,'family request immutable');END;
CREATE TRIGGER family_request_events_no_delete BEFORE DELETE ON family_request_events BEGIN SELECT RAISE(ABORT,'family request immutable');END;
CREATE TRIGGER family_request_root_text BEFORE INSERT ON family_request_roots WHEN length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 OR length(trim(NEW.request_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.request_note)>2000 OR instr(NEW.request_note,char(0))>0 OR NEW.time_status='recorded' AND (length(NEW.requested_start)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.requested_start) IS NOT NEW.requested_start OR length(NEW.requested_end)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.requested_end) IS NOT NEW.requested_end) BEGIN SELECT RAISE(ABORT,'family request explicit intent and desired time');END;
CREATE TRIGGER family_request_event_text BEFORE INSERT ON family_request_events WHEN length(trim(NEW.public_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.public_note)>2000 OR instr(NEW.public_note,char(0))>0 OR NEW.internal_reason IS NOT NULL AND (length(trim(NEW.internal_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.internal_reason)>300 OR instr(NEW.internal_reason,char(0))>0) BEGIN SELECT RAISE(ABORT,'family request explicit public response and separate internal reason');END;
